const b=$json.body||$json;
if(b.operation==='health')return [{json:{operation:'health'}}];
const allowed=['event_id','external_id','revision','name','due_at','end_at','status','company','contact_name','contact_email','contact_phone','meeting_url','notes'];
const p=Object.fromEntries(allowed.filter(k=>b[k]!==undefined).map(k=>[k,b[k]]));
for(const key of ['event_id','external_id','name','due_at','end_at','status'])if(typeof p[key]!=='string'||!p[key].trim())throw new Error('Campo obrigatório: '+key);
if(!Number.isInteger(p.revision)||p.revision<1)throw new Error('revision deve ser um inteiro positivo, crescente por reunião');
if(!['Aberto','Concluído','Cancelado'].includes(p.status))throw new Error('Situação inválida');
for(const k of ['due_at','end_at'])if(!/(Z|[+-]\d{2}:\d{2})$/.test(p[k])||!Number.isFinite(Date.parse(p[k])))throw new Error('Data deve informar fuso horário: '+k);
if(Date.parse(p.end_at)<=Date.parse(p.due_at))throw new Error('Fim deve ser posterior ao início');
if(p.meeting_url&&(!p.meeting_url.startsWith('https://')||/\s/.test(p.meeting_url)))throw new Error('Link da call deve usar HTTPS');
return [{json:{...p,operation:'upsert'}}];
